def name_the_codebook_everything_so_far_was_coded_under(apps, schema_editor):
    """Every cohort and decision before versions existed was coded under
    one codebook. Name it V1 and say so on each row, so that nothing
    coded later under V2 can be pooled with it by a missing value."""
    from review.classification import (
        CIN_LABELS,
        CODING_GUIDE,
        DEFAULT_INSTRUCTIONS,
        V1_REJECTIONS,
    )

    Version = apps.get_model("review", "CodebookVersion")
    Settings = apps.get_model("review", "CodebookSettings")
    live = Settings.objects.first()
    v1, _ = Version.objects.get_or_create(
        name="V1",
        defaults={
            # What coders were actually shown: the instructions as last
            # edited, where anybody edited them.
            "instructions": live.instructions if live else DEFAULT_INSTRUCTIONS,
            "guidance": {label: list(CODING_GUIDE[label]) for label in CIN_LABELS},
            "display_names": {},
            "rejections": list(V1_REJECTIONS),
        },
    )
    apps.get_model("review", "ClassificationCohort").objects.filter(
        codebook_version__isnull=True
    ).update(codebook_version=v1)
    apps.get_model("review", "ClassificationDecision").objects.filter(
        codebook_version__isnull=True
    ).update(codebook_version=v1)


